"""{NAME} ({ID}): current step in Brian2 (SpatialNeuron). Generated by hippsim (Neurons → Simulate → Run it in → Brian2).
Needs: pip install brian2 matplotlib, and {SWC_FILE} next to this script.
Model (same as hippsim's browser engine and the NEURON script): the reconstruction with leak Rm 20 kΩ·cm²,
Ri 150 Ω·cm, Cm 1 µF/cm² and Hodgkin–Huxley Na/K at 6.3 °C (gNa 0.5, gK 0.1 S/cm² in soma and axon, a fraction
of that in dendrites). Equations follow the Brian2 "spatial neuron" example. A starting point to edit."""
from brian2 import *
import matplotlib.pyplot as plt

# ---- settings (from hippsim; edit freely) ----
AMP = {AMP_NA}          # nA, 300 ms step starting at 50 ms
NA_SCALE = {NA_SCALE}     # × gNa 0.5 S/cm²
K_SCALE = {K_SCALE}      # × gK 0.1 S/cm²
DEND = {DEND_FRAC}       # dendritic channel density, fraction of soma
SITE = {SITE_XYZ}       # electrode: None = soma, or (x, y, z) in the SWC's µm coordinates ({SITE_LABEL})

def clean_swc(src, dst):
    """Brian2 needs every compartment to have length: drop points that sit exactly on their parent (re-parent children).
    Returns the root point's coordinates (Brian2 puts the root at the origin)."""
    rows = {}
    for line in open(src):
        if line.strip() and not line.startswith("#"):
            i, t, x, y, z, r, p = line.split()[:7]; rows[int(i)] = [int(t), float(x), float(y), float(z), max(float(r), 0.05), int(p)]   # radius ≥ 0.05 µm
    alias = {}
    for i, (t, x, y, z, r, p) in rows.items():
        p = alias.get(p, p)
        if p in rows and t != 1 and (x, y, z) == tuple(rows[p][1:4]): alias[i] = p
        rows[i][5] = p
    with open(dst, "w") as f:
        for i, (t, x, y, z, r, p) in rows.items():
            if i not in alias: f.write(f"{i} {t} {x} {y} {z} {r} {p}\n")
    root = next(v for v in rows.values() if v[5] == -1)
    return root[1:4]

defaultclock.dt = 0.025*ms
root = clean_swc("{SWC_FILE}", "brian2_{SWC_FILE}")
morpho = Morphology.from_file("brian2_{SWC_FILE}")
EL, ENa, EK = -65*mV, 50*mV, -77*mV
eqs = """
Im = gL*(EL - v) + gNa*m**3*h*(ENa - v) + gK*n**4*(EK - v) : amp/meter**2
I : amp (point current)
gNa : siemens/meter**2
gK : siemens/meter**2
dm/dt = alpham*(1-m) - betam*m : 1
dn/dt = alphan*(1-n) - betan*n : 1
dh/dt = alphah*(1-h) - betah*h : 1
alpham = (0.1/mV)*10*mV/exprel((-v - 40*mV)/(10*mV))/ms : Hz
betam = 4*exp((-v - 65*mV)/(18*mV))/ms : Hz
alphah = 0.07*exp((-v - 65*mV)/(20*mV))/ms : Hz
betah = 1/(exp((-v - 35*mV)/(10*mV)) + 1)/ms : Hz
alphan = (0.01/mV)*10*mV/exprel((-v - 55*mV)/(10*mV))/ms : Hz
betan = 0.125*exp((-v - 65*mV)/(80*mV))/ms : Hz
"""
gL = 1/(20*kohm*cm**2)
neuron = SpatialNeuron(morphology=morpho, model=eqs, method="exponential_euler",
                       Cm=1*uF/cm**2, Ri=150*ohm*cm, refractory="m > 0.4", threshold="m > 0.5")
def sections(s):
    yield s
    for c in s.children: yield from sections(c)
neuron.gNa = 500*DEND*NA_SCALE*msiemens/cm**2; neuron.gK = 100*DEND*K_SCALE*msiemens/cm**2   # dendrites
for s in sections(morpho):
    if s.type in ("soma", "axon"):                                                           # soma and axon: full density
        neuron[s].gNa = 500*NA_SCALE*msiemens/cm**2; neuron[s].gK = 100*K_SCALE*msiemens/cm**2
neuron.v = EL
neuron.m = 0.0529; neuron.h = 0.5961; neuron.n = 0.3177      # gates start at their steady state at -65 mV
k = 0
if SITE is not None:
    d = (neuron.x/um + root[0] - SITE[0])**2 + (neuron.y/um + root[1] - SITE[1])**2 + (neuron.z/um + root[2] - SITE[2])**2
    k = int(argmin(d))
mon = StateMonitor(neuron, "v", record=[0, k])
run(50*ms); neuron.I[k] = AMP*nA; run(300*ms); neuron.I[k] = 0*amp; run(50*ms)

tv, vs = mon.t/ms, mon[0].v/mV                                # spikes: soma crossing 0 mV (as in NEURON and hippsim)
st = [float(tv[i + 1]) for i in range(len(vs) - 1) if vs[i] < 0 <= vs[i + 1] and 50 <= tv[i + 1] < 350]
print(f"RESULT engine=Brian2 spikes={len(st)} first_ms={st[0] - 50 if st else 'none'}")
import os
if os.environ.get("HIPPSIM_TRACE"):                              # used by hippsim's engine check (soma V every 0.5 ms)
    print("TRACE", [round(float(x), 1) for x in vs[::20]])
print(f"{NAME}: {len(st)} spikes during a {AMP} nA, 300 ms step at {'the soma' if SITE is None else 'compartment %d' % k}")
plt.plot(mon.t/ms, mon[0].v/mV, lw=0.8, label="soma")
if k: plt.plot(mon.t/ms, mon[k].v/mV, lw=0.8, label="electrode")
plt.xlabel("time (ms)"); plt.ylabel("V (mV)"); plt.title("{NAME} ({ID}) · Brian2"); plt.legend(); plt.show()
